const items = $input.all();
const n = items.length;
if (n === 0) {
  return [{json: {send: false, count: 0}}];
}
// Agrupar por session_key para contar leads únicos
const bySess = {};
for (const it of items) {
  const k = it.json.session_key;
  if (!bySess[k]) bySess[k] = [];
  bySess[k].push(it.json);
}
const leadsUnicos = Object.keys(bySess).length;
// Top 5 leads más afectados
const tops = Object.entries(bySess).sort((a,b)=>b[1].length-a[1].length).slice(0,5);
const lines = tops.map(([sess, hits], i) => {
  const first = hits[hits.length-1]; // el mas viejo del período
  const nombre = first.lead_nombre || 'sin nombre';
  const prog = first.lead_programa || 'sin definir';
  return `${i+1}. ${nombre} (${sess}) · ${prog} · ${hits.length} hit(s)`;
}).join('\n');
const text = `✈️ VENTTUR — Digest 24h del guardrail\n\nGuardrail activado: ${n} vez(ces) en ${leadsUnicos} lead(s) distinto(s) durante las últimas 24 horas.\n\nTop por severidad:\n${lines}\n\nDetalle completo:\nhttps://[TU-INSTANCIA-N8N]/workflow/k3aivKSP67S97IHn/executions`;
return [{json: {send: true, count: n, leads: leadsUnicos, text}}];

